content.content:
1	// Package chainledger implements the on-chain data governance core.
2	//
3	// This file adds local lineage snapshots: a snapshot freezes one graph as a
4	// versioned, content-addressed JSON document, and two snapshots can be compared
5	// read-only. Every byte a snapshot writes is determined solely by the graph's
6	// semantics — dataset names and their direct upstreams — never by record
7	// order, upstream order, duplicate upstreams, JSON whitespace, save time, or
8	// file path.
9	package chainledger
10	
11	import (
12		"bytes"
13		"crypto/sha256"
14		"encoding/hex"
15		"encoding/json"
16		"errors"
17		"fmt"
18		"sort"
19		"strings"
20	)
21	
22	// SnapshotFormatVersion is the only on-disk snapshot format understood.
23	const SnapshotFormatVersion = 1
24	
25	// SnapshotFile is the on-disk representation of one frozen lineage graph.
26	//
27	// FormatVersion is fixed at 1. ContentID addresses the graph semantics and is
28	// verified against Graph on every read; Graph carries the complete graph.
29	type SnapshotFile struct {
30		FormatVersion int       `json:"formatVersion"`
31		ContentID     string    `json:"contentId"`
32		Graph         GraphFile `json:"graph"`
33	}
34	
35	// RootSourceChange reports that one dataset present in BOTH versions reaches a
36	// different set of root sources. OldRoots and NewRoots are sorted by name and
37	// never nil, so empty root sets encode as [] rather than null.
38	type RootSourceChange struct {
39		Dataset  string   `json:"dataset"`
40		OldRoots []string `json:"oldRoots"`
41		NewRoots []string `json:"newRoots"`
42	}
43	
44	// CompareReport is the deterministic, read-only diff of two snapshots read in
45	// the fixed direction old -> new.
46	//
47	// NewDatasets and RemovedDatasets list nodes present on only one side.
48	// ChangedDatasets lists datasets present on both sides whose direct upstream
49	// set actually changed. AddedRelations and RemovedRelations list every
50	// directed edge present on only one side, including edges that vanish because
51	// one endpoint node was removed. RootSourceChanges covers only datasets common
52	// to both versions whose reachable root set differs; added or removed datasets
53	// never appear there.
54	type CompareReport struct {
55		NewDatasets       []string           `json:"newDatasets"`
56		RemovedDatasets   []string           `json:"removedDatasets"`
57		ChangedDatasets   []string           `json:"changedDatasets"`
58		AddedRelations    []Relation         `json:"addedRelations"`
59		RemovedRelations  []Relation         `json:"removedRelations"`
60		RootSourceChanges []RootSourceChange `json:"rootSourceChanges"`
61	}
62	
63	// contentIDPrefix names the hash algorithm used for content addressing.
64	const contentIDPrefix = "sha256:"
65	
66	// graphAdjacencyFromFile builds the validated, normalized parent adjacency
67	// directly from a parsed graph file. It rejects empty names, duplicate
68	// datasets, and references to upstreams that are not declared; cycle checking
69	// is the caller's responsibility (via validateAcyclic) so the reported reason
70	// stays specific.
71	func graphAdjacencyFromFile(gf GraphFile) (adjacency, error) {
72		adj := make(adjacency, len(gf.Datasets))
73		for _, ds := range gf.Datasets {
74			if ds.Name == "" {
75				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
76			}
77			if _, exists := adj[ds.Name]; exists {
78				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
79			}
80			adj[ds.Name] = uniqueSorted(ds.Upstreams)
81		}
82		for name, parents := range adj {
83			for _, parent := range parents {
84				if _, ok := adj[parent]; !ok {
85					return nil, fmt.Errorf("%w: dataset %q references upstream %q which is not registered", ErrNotFound, name, parent)
86				}
87			}
88		}
89		return adj, nil
90	}
91	
92	// canonicalGraph serializes the graph's semantics deterministically: datasets
93	// sorted by name byte order with sorted, duplicate-free upstream lists, compact
94	// JSON with no insignificant whitespace. Two semantically equal graphs always
95	// produce identical bytes.
96	func canonicalGraph(adj adjacency) ([]byte, error) {
97		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
98		return json.Marshal(gf)
99	}
100	
101	// computeContentID returns the content identifier of the graph bytes:
102	// "sha256:" followed by the lowercase hex SHA-256 digest.
103	func computeContentID(canonical []byte) string {
104		sum := sha256.Sum256(canonical)
105		return contentIDPrefix + hex.EncodeToString(sum[:])
106	}
107	
108	// BuildSnapshot validates graph and freezes it into a SnapshotFile with format
109	// version 1 and the matching content identifier. It does not mutate graph. The
110	// returned document and its serialized bytes depend only on graph semantics.
111	func BuildSnapshot(graph map[string]*Lineage) (*SnapshotFile, error) {
112		if err := ValidateGraph(graph); err != nil {
113			return nil, err
114		}
115		adj, err := graphAdjacency(graph)
116		if err != nil {
117			return nil, err
118		}
119		canonical, err := canonicalGraph(adj)
120		if err != nil {
121			return nil, err
122		}
123		return &SnapshotFile{
124			FormatVersion: SnapshotFormatVersion,
125			ContentID:     computeContentID(canonical),
126			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
127		}, nil
128	}
129	
130	// MarshalSnapshot serializes a snapshot the same way for every save: indented
131	// JSON keyed by struct field order, terminated by a single newline.
132	func MarshalSnapshot(snap *SnapshotFile) ([]byte, error) {
133		var buf bytes.Buffer
134		enc := json.NewEncoder(&buf)
135		enc.SetIndent("", "  ")
136		enc.SetEscapeHTML(false)
137		if err := enc.Encode(snap); err != nil {
138			return nil, err
139		}
140		return buf.Bytes(), nil
141	}
142	
143	// rawSnapshot mirrors SnapshotFile but keeps each field raw so ParseSnapshot
144	// can distinguish "field absent" from "field present with a zero value"
145	// (e.g. a missing formatVersion must be rejected rather than read as 0).
146	type rawSnapshot struct {
147		FormatVersion json.RawMessage `json:"formatVersion"`
148		ContentID     json.RawMessage `json:"contentId"`
149		Graph         json.RawMessage `json:"graph"`
150	}
151	
152	// isJSONNull reports whether a raw JSON value is the literal null.
153	func isJSONNull(raw json.RawMessage) bool {
154		return string(bytes.TrimSpace(raw)) == "null"
155	}
156	
157	// ParseSnapshot parses and strictly validates one snapshot document: required
158	// fields must be present and well-typed, no known field may be declared twice
159	// within the same object (even with identical values, a null first, or a
160	// spelling equivalent under Unicode case folding or JSON escaping), the
161	// format version must be supported, the embedded graph must be structurally
162	// valid (no empty names, duplicate datasets, missing upstreams, or cycles),
163	// and the content identifier must correspond exactly to the graph. A
164	// tampered, corrupt, or otherwise invalid snapshot is rejected, so a bad file
165	// can never be trusted as a version.
166	func ParseSnapshot(data []byte) (*SnapshotFile, error) {
167		if err := checkDuplicateFields(data); err != nil {
168			return nil, err
169		}
170		var raw rawSnapshot
171		if err := json.Unmarshal(data, &raw); err != nil {
172			return nil, fmt.Errorf("invalid snapshot JSON: %w", err)
173		}
174		if len(raw.FormatVersion) == 0 {
175			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "formatVersion")
176		}
177		if len(raw.ContentID) == 0 {
178			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "contentId")
179		}
180		if len(raw.Graph) == 0 {
181			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "graph")
182		}
183		// An explicit JSON null is present-but-untyped and must not be silently
184		// treated as a zero value (in particular, graph:null must not read as an
185		// empty graph).
186		if isJSONNull(raw.FormatVersion) {
187			return nil, fmt.Errorf("%w: snapshot field %q must be a number, not null", ErrInvalidArgument, "formatVersion")
188		}
189		if isJSONNull(raw.ContentID) {
190			return nil, fmt.Errorf("%w: snapshot field %q must be a string, not null", ErrInvalidArgument, "contentId")
191		}
192		if isJSONNull(raw.Graph) {
193			return nil, fmt.Errorf("%w: snapshot field %q must be an object, not null", ErrInvalidArgument, "graph")
194		}
195	
196		var version int
197		if err := json.Unmarshal(raw.FormatVersion, &version); err != nil {
198			return nil, fmt.Errorf("%w: snapshot field %q must be a number: %v", ErrInvalidArgument, "formatVersion", err)
199		}
200		if version != SnapshotFormatVersion {
201			return nil, fmt.Errorf("%w: unsupported snapshot format version %d, supported version is %d", ErrInvalidArgument, version, SnapshotFormatVersion)
202		}
203	
204		var contentID string
205		if err := json.Unmarshal(raw.ContentID, &contentID); err != nil {
206			return nil, fmt.Errorf("%w: snapshot field %q must be a string", ErrInvalidArgument, "contentId")
207		}
208		if contentID == "" {
209			return nil, fmt.Errorf("%w: snapshot field %q must not be empty", ErrInvalidArgument, "contentId")
210		}
211	
212		var gf GraphFile
213		if err := json.Unmarshal(raw.Graph, &gf); err != nil {
214			return nil, fmt.Errorf("invalid graph in snapshot: %w", err)
215		}
216		adj, err := graphAdjacencyFromFile(gf)
217		if err != nil {
218			return nil, err
219		}
220		if err := validateAcyclic(adj); err != nil {
221			return nil, err
222		}
223	
224		canonical, err := canonicalGraph(adj)
225		if err != nil {
226			return nil, err
227		}
228		if want := computeContentID(canonical); contentID != want {
229			return nil, fmt.Errorf("%w: content identifier %q does not match the graph (expected %q); the snapshot was altered or corrupted", ErrInvalidArgument, contentID, want)
230		}
231	
232		return &SnapshotFile{
233			FormatVersion: version,
234			ContentID:     contentID,
235			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
236		}, nil
237	}
238	
239	// errAbortScan stops the duplicate-field scan when the document is too
240	// malformed to keep walking; the regular parse then reports the syntax or
241	// type error instead.
242	var errAbortScan = errors.New("chainledger: abort duplicate field scan")
243	
244	// checkDuplicateFields rejects a snapshot in which a known field is declared
245	// more than once within the same object: formatVersion, contentId, and graph
246	// at the top level, datasets inside graph, and name and upstreams inside each
247	// dataset record. A repeated field is ambiguous — the reader would silently
248	// keep only one declaration — so the whole snapshot is refused even when the
249	// duplicates carry identical values, the first is null, or the surviving value
250	// would pass every other check.
251	//
252	// Field names are compared after JSON string unescaping and with the same
253	// Unicode simple case-folding the decoder applies to its case-insensitive
254	// field lookup (equivalent to strings.EqualFold), so "name", "Name", and
255	// "name" all collide, and so do spellings that only differ in a fold
256	// equivalent rune such as "formatVerſion" (long s) and "formatVersion".
257	// Unknown fields keep their ignore-everything behavior and may repeat freely.
258	// Documents that are not shaped like a snapshot at all are left to the
259	// regular parse, which reports the structural problem.
260	func checkDuplicateFields(data []byte) error {
261		dec := json.NewDecoder(bytes.NewReader(data))
262		err := checkTopLevelObject(dec)
263		if errors.Is(err, errAbortScan) {
264			return nil
265		}
266		return err
267	}
268	
269	// checkTopLevelObject scans the top-level snapshot object for repeated
270	// formatVersion/contentId/graph declarations, descending into graph values.
271	func checkTopLevelObject(dec *json.Decoder) error {
272		tok, err := scanToken(dec)
273		if err != nil {
274			return err
275		}
276		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
277			return nil // not an object: the regular parse reports the type error
278		}
279		seen := make(map[string]bool, 3)
280		for dec.More() {
281			key, err := scanKey(dec)
282			if err != nil {
283				return err
284			}
285			field, known := snapshotField(key)
286			if known {
287				if seen[field] {
288					return duplicateFieldError(field, "at the top level of the snapshot")
289				}
290				seen[field] = true
291			}
292			if field == "graph" {
293				if err := checkGraphValue(dec); err != nil {
294					return err
295				}
296			} else if err := skipValue(dec); err != nil {
297				return err
298			}
299		}
300		_, err = scanToken(dec) // closing '}'
301		return err
302	}
303	
304	// checkGraphValue scans one graph value for a repeated datasets declaration,
305	// descending into each dataset record of the datasets array.
306	func checkGraphValue(dec *json.Decoder) error {
307		tok, err := scanToken(dec)
308		if err != nil {
309			return err
310		}
311		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
312			// Not an object (null, array, scalar): consume any remainder and let
313			// the regular parse report the type problem.
314			return skipRest(dec, tok)
315		}
316		seen := false
317		for dec.More() {
318			key, err := scanKey(dec)
319			if err != nil {
320				return err
321			}
322			if strings.EqualFold(key, "datasets") {
323				if seen {
324					return duplicateFieldError("datasets", `in "graph"`)
325				}
326				seen = true
327				if err := checkDatasetsValue(dec); err != nil {
328					return err
329				}
330			} else if err := skipValue(dec); err != nil {
331				return err
332			}
333		}
334		_, err = scanToken(dec) // closing '}'
335		return err
336	}
337	
338	// checkDatasetsValue scans one datasets array, checking every record that is
339	// an object for repeated name/upstreams declarations.
340	func checkDatasetsValue(dec *json.Decoder) error {
341		tok, err := scanToken(dec)
342		if err != nil {
343			return err
344		}
345		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
346			return skipRest(dec, tok) // not an array: the regular parse reports it
347		}
348		for index := 0; dec.More(); index++ {
349			if err := checkDatasetRecord(dec, index); err != nil {
350				return err
351			}
352		}
353		_, err = scanToken(dec) // closing ']'
354		return err
355	}
356	
357	// checkDatasetRecord scans one element of the datasets array. If it is an
358	// object, name and upstreams must each be declared at most once.
359	func checkDatasetRecord(dec *json.Decoder, index int) error {
360		tok, err := scanToken(dec)
361		if err != nil {
362			return err
363		}
364		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
365			return skipRest(dec, tok) // not an object: the regular parse reports it
366		}
367		seen := make(map[string]bool, 2)
368		for dec.More() {
369			key, err := scanKey(dec)
370			if err != nil {
371				return err
372			}
373			if field, known := datasetField(key); known {
374				if seen[field] {
375					return duplicateFieldError(field, fmt.Sprintf("in the dataset record at index %d of \"datasets\"", index))
376				}
377				seen[field] = true
378			}
379			if err := skipValue(dec); err != nil {
380				return err
381			}
382		}
383		_, err = scanToken(dec) // closing '}'
384		return err
385	}
386	
387	// duplicateFieldError reports a known field declared twice, naming the field
388	// and where in the document the repetition occurred.
389	func duplicateFieldError(field, location string) error {
390		return fmt.Errorf("%w: field %q is declared more than once %s", ErrInvalidArgument, field, location)
391	}
392	
393	// snapshotField maps a top-level key to the canonical name of the snapshot
394	// field it selects, matching the decoder's case-insensitive field lookup.
395	func snapshotField(key string) (string, bool) {
396		switch {
397		case strings.EqualFold(key, "formatVersion"):
398			return "formatVersion", true
399		case strings.EqualFold(key, "contentId"):
400			return "contentId", true
401		case strings.EqualFold(key, "graph"):
402			return "graph", true
403		}
404		return "", false
405	}
406	
407	// datasetField maps a dataset-record key to the canonical name of the record
408	// field it selects, matching the decoder's case-insensitive field lookup.
409	func datasetField(key string) (string, bool) {
410		switch {
411		case strings.EqualFold(key, "name"):
412			return "name", true
413		case strings.EqualFold(key, "upstreams"):
414			return "upstreams", true
415		}
416		return "", false
417	}
418	
419	// scanToken reads one token; any decode failure aborts the scan so the
420	// regular parse can report the malformed document.
421	func scanToken(dec *json.Decoder) (json.Token, error) {
422		tok, err := dec.Token()
423		if err != nil {
424			return nil, errAbortScan
425		}
426		return tok, nil
427	}
428	
429	// scanKey reads the next key of the object currently being walked.
430	func scanKey(dec *json.Decoder) (string, error) {
431		tok, err := scanToken(dec)
432		if err != nil {
433			return "", err
434		}
435		key, ok := tok.(string)
436		if !ok {
437			return "", errAbortScan
438		}
439		return key, nil
440	}
441	
442	// skipValue consumes one complete JSON value.
443	func skipValue(dec *json.Decoder) error {
444		tok, err := scanToken(dec)
445		if err != nil {
446			return err
447		}
448		return skipRest(dec, tok)
449	}
450	
451	// skipRest consumes the remainder of a value whose first token is tok.
452	func skipRest(dec *json.Decoder, tok json.Token) error {
453		delim, ok := tok.(json.Delim)
454		if !ok {
455			return nil // scalar, fully consumed already
456		}
457		var closer json.Delim
458		switch delim {
459		case '{':
460			closer = '}'
461			for dec.More() {
462				if _, err := scanKey(dec); err != nil {
463					return err
464				}
465				if err := skipValue(dec); err != nil {
466					return err
467				}
468			}
469		case '[':
470			closer = ']'
471			for dec.More() {
472				if err := skipValue(dec); err != nil {
473					return err
474				}
475			}
476		default:
477			return errAbortScan
478		}
479		tok, err := scanToken(dec)
480		if err != nil {
481			return err
482		}
483		if end, ok := tok.(json.Delim); !ok || end != closer {
484			return errAbortScan
485		}
486		return nil
487	}
488	
489	// CompareSnapshots returns the fixed-direction diff from old to new. Both
490	// inputs are assumed to have passed ParseSnapshot; the report is fully
491	// deterministic and identical for semantically identical comparisons.
492	func CompareSnapshots(oldSnap, newSnap *SnapshotFile) *CompareReport {
493		oldAdj := adjacencyFromValidFile(oldSnap.Graph)
494		newAdj := adjacencyFromValidFile(newSnap.Graph)
495	
496		added, removed := diffRelations(oldAdj, newAdj)
497	
498		var newNodes, removedNodes, changedNodes []string
499		for name := range newAdj {
500			if oldParents, ok := oldAdj[name]; !ok {
501				newNodes = append(newNodes, name)
502			} else if !stringSliceEqual(oldParents, newAdj[name]) {
503				changedNodes = append(changedNodes, name)
504			}
505		}
506		for name := range oldAdj {
507			if _, ok := newAdj[name]; !ok {
508				removedNodes = append(removedNodes, name)
509			}
510		}
511		sort.Strings(newNodes)
512		sort.Strings(removedNodes)
513		sort.Strings(changedNodes)
514	
515		common := make([]string, 0)
516		for name := range oldAdj {
517			if _, ok := newAdj[name]; ok {
518				common = append(common, name)
519			}
520		}
521		sort.Strings(common)
522	
523		rootChanges := make([]RootSourceChange, 0)
524		for _, name := range common {
525			oldRoots := rootSources(name, oldAdj)
526			newRoots := rootSources(name, newAdj)
527			if !stringSliceEqual(oldRoots, newRoots) {
528				rootChanges = append(rootChanges, RootSourceChange{
529					Dataset:  name,
530					OldRoots: oldRoots,
531					NewRoots: newRoots,
532				})
533			}
534		}
535	
536		return &CompareReport{
537			NewDatasets:       orEmptyStrings(newNodes),
538			RemovedDatasets:   orEmptyStrings(removedNodes),
539			ChangedDatasets:   orEmptyStrings(changedNodes),
540			AddedRelations:    orEmptyRelations(added),
541			RemovedRelations:  orEmptyRelations(removed),
542			RootSourceChanges: rootChanges,
543		}
544	}
545	
546	// adjacencyFromValidFile builds normalized parent adjacency from an already
547	// validated graph file.
548	func adjacencyFromValidFile(gf GraphFile) adjacency {
549		adj := make(adjacency, len(gf.Datasets))
550		for _, ds := range gf.Datasets {
551			adj[ds.Name] = uniqueSorted(ds.Upstreams)
552		}
553		return adj
554	}
555	
556	// rootSources returns the root datasets reachable from node by following
557	// direct upstream edges. A node without upstreams is itself a root and its own
558	// source, so it is included. Nodes reached by more than one path count once.
559	// The result is sorted by name and never nil.
560	func rootSources(node string, adj adjacency) []string {
561		visited := make(map[string]bool)
562		var roots []string
563		var walk func(string)
564		walk = func(current string) {
565			if visited[current] {
566				return
567			}
568			visited[current] = true
569			parents := adj[current]
570			if len(parents) == 0 {
571				roots = append(roots, current)
572				return
573			}
574			for _, parent := range parents {
575				walk(parent)
576			}
577		}
578		walk(node)
579		sort.Strings(roots)
580		return orEmptyStrings(roots)
581	}
582	
583	func orEmptyStrings(s []string) []string {
584		if s == nil {
585			return []string{}
586		}
587		return s
588	}
589	
590	func orEmptyRelations(r []Relation) []Relation {
591		if r == nil {
592			return []Relation{}
593		}
594		return r
595	}
596

